export const BODY: string = "\n<p>متن تصویر کو پیغام بنا دیتا ہے۔ کیپشن بتاتا ہے کہ تصویر میں کیا ہے، عنوان اسے نام دیتا ہے، اور اقتباس اسے آواز دیتا ہے۔</p>\n<p>تصویر پر متن لگانا ایک سادہ مہارت ہے جس کے بہت سے استعمال ہیں: سوشل پوسٹس، میمز، پریزنٹیشن، پروڈکٹ لیبل اور نوٹ والی اسکرین شاٹس سب اس پر انحصار کرتے ہیں۔</p>\n<p>اس گائیڈ میں بتایا گیا ہے کہ متن اچھی طرح کیسے لگائیں۔ اس میں فونٹ، سائز، رنگ، کنٹراسٹ، آؤٹ لائن، پوزیشن اور وہ غلطیاں شامل ہیں جن سے متن ناقابلِ پڑھائی بن جاتا ہے۔</p>\n<h2 id=\"what-text-on-image-does\">تصویر پر متن کیا کرتا ہے</h2>\n<p>متن وہ معنی دیتا ہے جو تصویر اکیلی نہیں دے سکتی۔ پہاڑ کی تصویر صرف پہاڑ ہوتی ہے، مگر کیپشن کے ساتھ وہی تصویر یاد، مذاق یا کہانی بن جاتی ہے۔</p>\n<p>متن سیاق بھی دیتا ہے۔ تصویر پر لکھی تاریخ، جگہ یا نام دیکھنے والے کو بتاتا ہے کہ وہ کیا دیکھ رہا ہے، بغیر الگ وضاحت کے۔</p>\n<p>کاروبار کے لیے تصویر پر متن لیبل ہوتا ہے۔ قیمت والی پروڈکٹ فوٹو، ڈسکاؤنٹ والا سیل بینر، یا تاریخ والا پوسٹر سب متن سے بیچتے ہیں۔</p>\n<p>اہم بات تحمل ہے۔ چند اچھی جگہ رکھے الفاظ تصویر کو مضبوط کرتے ہیں، جبکہ تصویر پر بھرا ہوا پیراگراف اسی چیز کو چھپا دیتا ہے جسے بیان کرنا تھا۔</p>\n<h2 id=\"captions-vs-watermarks\">کیپشن، عنوان اور واٹر مارک الگ الگ کام ہیں</h2>\n<p>کیپشن تصویر کی وضاحت کرتا ہے۔ یہ موضوع کے قریب بیٹھتا ہے، پڑھنے میں آسان ہوتا ہے، اور ہر دیکھنے والے کے لیے ہوتا ہے۔</p>\n<p>عنوان تصویر کو نام دیتا ہے۔ یہ عام طور پر کیپشن سے بڑا اور بولڈ ہوتا ہے، اور صفحے یا پوسٹ کی باقی چیزوں کا لہجہ طے کرتا ہے۔</p>\n<p>واٹر مارک تصویر کی حفاظت کرتا ہے۔ یہ مالک کی پہچان بتاتا ہے، اکثر نیم شفاف ہوتا ہے، اور کاپی اور دوبارہ پوسٹ ہونے پر بھی بچا رہتا ہے۔</p>\n<p>تینوں کو نہ ملائیں۔ جو کیپشن واٹر مارک جیسا لگے اسے نظر انداز کر دیا جائے گا، اور جو واٹر مارک کیپشن جیسا لگے وہ کچھ بھی محفوظ نہیں کرے گا۔</p>\n<h2 id=\"fonts-explained\">فونٹ: موزوں ٹائپ فیس چننا</h2>\n<p>فونٹ لفظ پڑھنے سے پہلے ہی متن کا مزاج طے کر دیتا ہے۔ بولڈ سینز سیرف جدید اور سیدھا لگتا ہے، جبکہ سیرف کلاسک اور رسمی لگتا ہے۔</p>\n<p>ایسا فونٹ چنیں جو تصویر سے میل کھائے۔ کھلکھلاہٹ والے میم کو بولڈ، بھاری فونٹ چاہیے ہوتا ہے، جبکہ شادی کی تصویر کو نفیس اور ہلکا فونٹ چاہیے ہوتا ہے۔</p>\n<p>فی تصویر ایک یا دو فونٹ تک محدود رہیں۔ بہت سے ٹائپ فیس ملانا افراتفری لگتا ہے، جبکہ ایک مستقل فونٹ ڈیزائن کو صاف اور پیشہ ورانہ رکھتا ہے۔</p>\n<p>فونٹ اس سائز پر چیک کریں جس پر آپ اسے استعمال کریں گے۔ جو آرائشی فونٹ بڑے سائز پر خوبصورت لگے وہ چھوٹے ہونے پر ناقابلِ پڑھائی بن سکتا ہے۔</p>\n<h2 id=\"text-size-scaling\">متن کا سائز: چھوٹی تصاویر بمقابلہ بڑی تصاویر</h2>\n<p>متن کا سائز تصویر کے 2 فیصد سے 22 فیصد تک مقرر ہوتا ہے۔ اس کا مطلب ہے کہ ایک ہی سیٹنگ چھوٹے تھمب نیل اور بڑے کیمرے کی تصویر دونوں پر مستقل لگتی ہے۔</p>\n<p>جو سائز بڑی تصویر پر درست لگے وہ چھوٹی تصویر پر پکسل میں مقرر ہو تو نظر ہی نہ آئے۔ فیصد سائزنگ اس مسئلے کو مکمل ختم کر دیتی ہے۔</p>\n<p>سرخی کے لیے حد کے اوپری حصے کے قریب بڑا سائز استعمال کریں۔ کیپشن یا کریڈٹ لائن کے لیے چھوٹا سائز استعمال کریں جو تصویر پر حاوی ہوئے بغیر پڑھنے کے قابل رہے۔</p>\n<p>متن اس اصل سائز پر چیک کریں جس پر آپ شیئر کریں گے۔ جو سرخی پورے سائز پر بولڈ لگے وہ سوشل فیڈ کے پیش نظارہ میں چھوٹی ہو سکتی ہے۔</p>\n<h2 id=\"colour-and-contrast\">رنگ اور کنٹراسٹ: متن کو پڑھنے کے قابل بنانا</h2>\n<p>سفید متن گہرے پس منظر پر اور سیاہ متن ہلکے پس منظر پر کام کرتا ہے، مگر زیادہ تر تصاویر میں دونوں ہوتے ہیں۔ ایک رنگ تصویر میں کہیں نہ کہیں ضرور غائب ہو جائے گا۔</p>\n<p>متن کو پڑھنے کے قابل کنٹراسٹ بناتا ہے، صرف رنگ نہیں۔ روشن پس منظر پر روشن رنگ ناکام ہوتا ہے، اور گہرے پس منظر پر گہرا رنگ بھی اتنا ہی برا ناکام ہوتا ہے۔</p>\n<p>متن تصویر کے سب سے سادہ حصے پر رکھیں۔ صاف آسمان یا خالی دیوار پر کیپشن مصروف بھیڑ یا جنگل پر کیپشن سے کہیں آسان پڑھا جاتا ہے۔</p>\n<p>جب کوئی سادہ جگہ نہ ہو تو پس منظر پینل شامل کریں۔ سفید متن کے پیچھے نیم شفاف گہرا ڈبہ اسے ہر جگہ پڑھنے کے قابل بنا دیتا ہے، چاہے وہ تصویر کا زیادہ حصہ ڈھانپ لے۔</p>\n<h2 id=\"outline-and-shadow\">آؤٹ لائن اور ڈراپ شیڈو</h2>\n<p>آؤٹ لائن ہر حرف کے گرد کھینچی گئی سرحد ہوتی ہے۔ سفید متن کے گرد پتلی گہری آؤٹ لائن اسے روشن آسمان پر پڑھنے کے قابل رکھتی ہے، اسی لیے میمز اسے استعمال کرتے ہیں۔</p>\n<p>ڈراپ شیڈو متن کو پس منظر سے اٹھا دیتا ہے۔ یہ حروف کے پیچھے نرم گہرا کنارہ بڑھاتا ہے، جو آؤٹ لائن کی سخت شکل کے بغیر انہیں نمایاں ہونے میں مدد دیتا ہے۔</p>\n<p>ایک یا دوسرا استعمال کریں، دونوں پوری شدت سے نہیں۔ آؤٹ لائن اور بھاری شیڈو مل کر متن کو بھرا ہوا لگاتے ہیں، جبکہ ایک اثر اسے صاف رکھتا ہے۔</p>\n<p>کلاسک میم متن کے لیے موٹی گہری آؤٹ لائن والے سفید حروف استعمال کریں۔ یہ ترکیب تقریباً ہر پس منظر پر پڑھنے کے قابل ہوتی ہے، اسی لیے یہ معیار بن گئی۔</p>\n<h2 id=\"positioning-and-layers\">پوزیشن اور لیئرز</h2>\n<p>متن کی لیئرز کو تصویر پر کہیں بھی لے جایا جا سکتا ہے۔ لیئر کو کھینچ کر رکھیں، اور ٹول آپ کو ہر لیئر کو الگ الگ منتخب کرنے دیتا ہے جب آپ کے پاس کئی ہوں۔</p>\n<p>اوپر اور نیچے کیپشن کے لیے کلاسک جگہیں ہیں۔ اوپر سرخی اور نیچے پنچ لائن میم فارمیٹ ہے، اور یہ اس لیے کام کرتا ہے کیونکہ آنکھ اوپر سے نیچے پڑھتی ہے۔</p>\n<p>متن کو کناروں سے دور رکھیں۔ سرحد سے چپکا کیپشن تنگ لگتا ہے، اور پلیٹفارم اکثر مختلف اسکرین سائز کے لیے کنارے دوبارہ کراپ کر دیتے ہیں۔</p>\n<p>جب آپ کے پاس کئی لیئرز ہوں تو بدلنے سے پہلے وہ لیئر منتخب کریں جسے ایڈٹ کرنا ہو۔ غلط لیئر ایڈٹ کرنا عام غلطی ہے، اور چیک کر کے اس سے بچنا آسان ہے۔</p>\n<h2 id=\"rotating-text\">اثر کے لیے متن گھمانا</h2>\n<p>متن کو اپنی مرضی کے زاویوں پر جھکایا جا سکتا ہے، جو ڈیزائن میں توانائی بڑھاتا ہے۔ کچھ ترچھی سرخی متحرک لگتی ہے، جبکہ سیدھا متن پرسکون اور رسمی لگتا ہے۔</p>\n<p>گھماؤ کم استعمال کریں۔ چند ڈگری کا چھوٹا جھکاؤ شخصیت بڑھاتا ہے، جبکہ تیز زاویہ متن کو پڑھنا مشکل بنا دیتا ہے اور غلطی لگتا ہے۔</p>\n<p>ترچھا متن پوسٹر اور سوشل گرافکس پر اچھا کام کرتا ہے، جہاں ڈیزائن آنکھ پکڑنے کے لیے ہوتا ہے۔ ہدایات اور لیبل پر یہ خراب کام کرتا ہے، جہاں وضاحت اہمیت رکھتی ہے۔</p>\n<p>گھمایا ہوا متن اس سائز پر چیک کریں جس پر اسے دیکھا جائے گا۔ جو جھکاؤ پورے سائز پر ٹھیک لگے وہ فیڈ پیش نظارہ میں چھوٹا متن ناقابلِ پڑھائی بنا سکتا ہے۔</p>\n<h2 id=\"multi-line-text\">کئی لائنوں والے کیپشن</h2>\n<p>متن کے اندر Enter دبانے سے نئی لائن بنتی ہے۔ اس سے آپ دو یا تین لائنوں کا کیپشن لکھ سکتے ہیں بغیر ہر لائن کے لیے الگ لیئر بنائے۔</p>\n<p>لائنیں چھوٹی رکھیں۔ تصویر کی پوری چوڑائی پر چلنے والا کیپشن پڑھنا مشکل ہوتا ہے، جبکہ موضوع پر مرکوز چھوٹی لائنیں آسانی سے پڑھی جاتی ہیں۔</p>\n<p>لائنیں جملے کے قدرتی وقفوں پر توڑیں۔ جملے کے بیچ میں لائن ٹوٹنا عجیب لگتا ہے، جبکہ جملوں کے درمیان ٹوٹنا جان بوجھ کر لگتا ہے۔</p>\n<p>میم کے لیے اوپر والے کیپشن کے لیے ایک لیئر اور نیچے والے کے لیے ایک لیئر استعمال کریں۔ الگ لیئرز آپ کو ہر لائن کو بالکل اس کی جگہ رکھنے دیتی ہیں۔</p>\n<h2 id=\"memes\">میمز بنانا</h2>\n<p>میم ایک تصویر ہوتی ہے جس پر مختصر، مضحکہ خیز کیپشن ہوتا ہے، عام طور پر اوپر اور نیچے موٹی گہری آؤٹ لائن والا سفید متن۔ فارمیٹ سادہ ہے، اور یہ سادگی ہی اس کی طاقت ہے۔</p>\n<p>متن مختصر رکھیں۔ پیراگراف والے متن کا میم مضحکہ خیز نہیں ہوتا، کیونکہ مذاق والی تصویر پر کوئی پیراگراف نہیں پڑھتا۔ اوپر ایک لائن اور نیچے ایک لائن کافی ہوتی ہے۔</p>\n<p>بولڈ، بھاری فونٹ استعمال کریں۔ کلاسک میم شکل میں بھاری سینز سیرف استعمال ہوتا ہے جو چھوٹے سائز اور مصروف پس منظر پر بھی پڑھنے کے قابل رہتا ہے۔</p>\n<p>پہلے اوپر والی لائن رکھیں اور پھر نیچے والی۔ آنکھ اوپر سیٹ اپ پڑھتی ہے، تصویر دیکھتی ہے، اور پھر نیچے پنچ لائن پڑھتی ہے۔</p>\n<h2 id=\"quotes-and-titles\">اقتباسات، عنوانات اور سوشل گرافکس</h2>\n<p>تصویر پر اقتباس مقبول سوشل فارمیٹ ہے۔ متن عام طور پر بڑا، بیچ میں، اور تصویر کے سادہ حصے یا گہرے پس منظر پر رکھا جاتا ہے۔</p>\n<p>اقتباسات مختصر رکھیں۔ ایک جملہ پیراگراف سے کہیں بہتر کام کرتا ہے، کیونکہ تصویر اور الفاظ جگہ بانٹتے ہیں اور کوئی بھی غالب نہیں ہونا چاہیے۔</p>\n<p>عنوانات کے لیے کیپشن سے بڑا سائز اور بولڈ فونٹ استعمال کریں۔ عنوان سب سے پہلے آنکھ کو ملنا چاہیے، اور تصویر اس کی حمایت کرے، اس سے مقابلہ نہ کرے۔</p>\n<p>جب تصویر مصروف ہو تو متن کے پیچھے تصویر کو کچھ گہرا کریں۔ نیم شفاف اوورلے سفید متن کو تصویر کو مکمل چھپائے بغیر پڑھنے کے قابل بنا دیتا ہے۔</p>\n<h2 id=\"annotations\">تشریحات اور لیبل</h2>\n<p>تشریحات تصویر کے حصوں کی وضاحت کرتی ہیں۔ تیر والا لیبل، نمبر والا مرحلہ، یا مختصر نوٹ اسکرین شاٹ کو ہدایات بنا دیتا ہے۔</p>\n<p>تشریحات مختصر رکھیں اور انہیں اس چیز کے قریب رکھیں جسے وہ بیان کرتی ہیں۔ موضوع سے دور لیبل دیکھنے والے کو الجھاتا ہے، جبکہ بالکل پاس والا لیبل واضح ہوتا ہے۔</p>\n<p>ایک تصویر پر تمام تشریحات کے لیے مستقل انداز استعمال کریں۔ ہر لیبل کے لیے ایک ہی فونٹ، سائز اور رنگ تصویر کو پیشہ ورانہ اور آسانی سے سمجھنے کے قابل بناتا ہے۔</p>\n<p>اسکرین شاٹس کے لیے کراپ کرنے کے بعد Add Text to Image ٹول سے تشریح کریں۔ مضبوط کراپ اور چند صاف لیبل بغیر تشریح والے پورے اسکرین شاٹ سے کہیں زیادہ مفید ہوتے ہیں۔</p>\n<h2 id=\"formats-and-export\">فارمیٹ اور ایکسپورٹ</h2>\n<p>ٹول عام تصویری فارمیٹ قبول کرتا ہے، جن میں JPG، PNG، WebP اور HEIC شامل ہیں، اور فائلیں 20 MB تک ہو سکتی ہیں۔ آپ اپنی ضرورت کے مطابق JPG، PNG یا WebP میں ایکسپورٹ کر سکتے ہیں۔</p>\n<p>PNG یا WebP میں ایکسپورٹ کرنے سے بنیادی تصویر میں شفافیت محفوظ رہتی ہے۔ اگر آپ کا ماخذ شفاف PNG اسٹیکر ہے تو متن والی ایکسپورٹ شفاف جگہوں کو برقرار رکھتی ہے۔</p>\n<p>متن والی تصاویر کے لیے اعلیٰ کوالٹی سیٹنگ پر JPG اچھا کام کرتا ہے۔ JPG کمپریشن کے تحت متن کے کنارے کچھ نرم ہو سکتے ہیں، اس لیے چھوٹے کیپشن کے لیے کوالٹی زیادہ رکھیں۔</p>\n<p>کوالٹی سلائیڈر JPG اور WebP ایکسپورٹ کے لیے ظاہر ہوتا ہے اور PNG کے لیے چھپ جاتا ہے، کیونکہ PNG لاس لیس ہے اور اس کی کوئی کوالٹی سیٹنگ نہیں ہوتی۔</p>\n<h2 id=\"privacy-local-processing\">پرائیویسی: اپ لوڈ کیے بغیر متن شامل کرنا</h2>\n<p>تمام متن ایڈیٹنگ آپ کے براؤزر میں ہوتی ہے۔ آپ کی تصاویر کبھی سرور پر اپ لوڈ نہیں ہوتیں، جو اہمیت رکھتا ہے جب تصاویر ذاتی ہوں، خاندانی تصاویر ہوں یا کام کی اسکرینیں ہوں۔</p>\n<p>یہ کلاؤڈ ایڈیٹرز پر حقیقی فائدہ ہے۔ کیپشن والی خاندانی تصویر چند الفاظ شامل کرنے کے لیے ایسے سرور پر نہیں جانی چاہیے جسے آپ دیکھ نہیں سکتے۔</p>\n<p>ٹول ایکسپورٹ پر EXIF GPS ڈیٹا بھی ہٹا دیتا ہے۔ ٹول سے ڈاؤن لوڈ شدہ کیپشن والی تصویر میں یہ ریکارڈ نہیں ہوتا کہ وہ کہاں لی گئی تھی۔</p>\n<p>بغیر متن والی اصل تصویر رکھیں۔ ایک بار متن ایکسپورٹ میں جڑ جائے تو اسے اس فائل سے ہٹایا نہیں جا سکتا، اس لیے اصل ہی آپ کی واحد صاف کاپی ہے۔</p>\n<h2 id=\"common-mistakes\">متن لگاتے وقت عام غلطیاں</h2>\n<p>سب سے عام غلطی بہت چھوٹا متن ہے۔ جو کیپشن پورے سائز پر ٹھیک لگے وہ سوشل فیڈ میں ناقابلِ پڑھائی ہو سکتا ہے، جہاں تصویر کہیں چھوٹی دکھائی جاتی ہے۔</p>\n<p>دوسری غلطی خراب کنٹراسٹ ہے۔ روشن آسمان پر سفید متن اور گہرے پس منظر پر سیاہ متن دونوں غائب ہو جاتے ہیں، اس لیے متن کو اصل تصویر پر چیک کریں، خالی پس منظر پر نہیں۔</p>\n<p>لوگ بہت زیادہ بھی لکھتے ہیں۔ تصویر پر پیراگراف تصویر کو چھپاتا ہے اور دیکھنے والے کو مغلوب کر دیتا ہے، جبکہ چند چنے ہوئے الفاظ کام بہتر کرتے ہیں۔</p>\n<p>آخر میں، متن وہاں نہ رکھیں جہاں پلیٹفارم اسے کراپ کر دے۔ سوشل ایپس مختلف اسکرینوں کے لیے تصاویر کے کنارے کاٹ دیتی ہیں، اس لیے اہم الفاظ کو اندر رکھیں۔</p>\n<h2 id=\"text-on-product-photos\">پروڈکٹ فوٹو پر متن</h2>\n<p>پروڈکٹ فوٹو میں اکثر مختصر متن ہوتا ہے: قیمت، ڈسکاؤنٹ یا خصوصیت۔ متن بڑا، بولڈ ہونا چاہیے اور وہاں رکھا جائے جہاں وہ پروڈکٹ کو نہ ڈھانپے۔</p>\n<p>قیمت یا پیشکش کو کونے میں رکھیں، بیچ میں نہیں۔ کونے والا لیبل پروڈکٹ کو نظر آنے دیتا ہے، جبکہ بیچ والا لیبل اسی چیز کو چھپاتا ہے جسے آپ بیچ رہے ہیں۔</p>\n<p>پورے کیٹلاگ میں مستقل انداز استعمال کریں۔ ہر قیمت لیبل کے لیے ایک ہی فونٹ، سائز اور رنگ دکان کو پیشہ ورانہ اور قابلِ اعتماد بناتا ہے۔</p>\n<p>متن مختصر رکھیں۔ قیمت اور ایک لفظ، جیسے Sale یا New، کافی ہے۔ پروڈکٹ فوٹو پر پیراگراف خریدار کی توجہ پروڈکٹ سے ہٹا دیتا ہے۔</p>\n<p>مرحلہ بہ مرحلہ عمل کے لیے <a href=\"/ur/blog/tasveer-par-text-kaise-likhein/\">How to Add Text to an Image</a> دیکھیں۔ پڑھنے کے اصولوں کے لیے <a href=\"/ur/blog/tasveer-par-text-readability-tips/\">Text on Images: Fonts, Contrast and Readability</a> پڑھیں، اور ملکیت کے نشان کے لیے <a href=\"/ur/tasveer-par-watermark-lagayein/\">Image Watermark tool</a> استعمال کریں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"تصویر پر متن کے لیے بہترین فونٹ کون سا ہے؟","answer":"زیادہ تر تصاویر کے لیے بولڈ سینز سیرف سب سے محفوظ انتخاب ہے، کیونکہ یہ چھوٹے سائز اور مصروف پس منظر پر بھی پڑھنے کے قابل رہتا ہے۔ سیرف فونٹ شادی کی تصاویر جیسی رسمی تصاویر کے لیے موزوں ہیں، جبکہ آرائشی فونٹ صرف بڑے عنوانات کے لیے اچھے ہوتے ہیں۔"},{"question":"روشن تصویر پر سفید متن کیسے پڑھنے کے قابل بناؤں؟","answer":"حروف کے گرد گہری آؤٹ لائن یا ڈراپ شیڈو شامل کریں، جو انہیں روشن جگہوں پر بھی نظر آنے دیتا ہے۔ متن کو تصویر کے سب سے گہرے حصے پر رکھنا بھی مدد کرتا ہے۔ متن کے پیچھے نیم شفاف گہرا پینل تقریباً ہر پس منظر پر کام کرتا ہے۔"},{"question":"کیا میں تصویر پر ایک سے زیادہ لائن متن لگا سکتا ہوں؟","answer":"ہاں۔ اسی لیئر میں نئی لائن بنانے کے لیے متن کے اندر Enter دبائیں، یا ہر لائن کے لیے الگ لیئر شامل کریں۔ الگ لیئرز آپ کو اوپر والا کیپشن اور نیچے والا کیپشن آزادانہ طور پر رکھنے دیتی ہیں۔"},{"question":"متن لگانے اور واٹر مارک لگانے میں کیا فرق ہے؟","answer":"متن لگانے سے کیپشن، عنوان یا تشریح بنتی ہے جو سب کے پڑھنے کے لیے ہوتی ہے۔ واٹر مارک لگانے سے نیم شفاف ملکیت کا نشان لگتا ہے جو کاپی ہونے پر بھی بچا رہے۔ پیغام کے لیے متن ٹول اور ملکیت کے لیے واٹر مارک ٹول استعمال کریں۔"},{"question":"سوشل میڈیا کے لیے تصویر پر متن کتنا بڑا ہونا چاہیے؟","answer":"اتنا بڑا کہ چھوٹے فیڈ پیش نظارہ میں بھی پڑھا جا سکے، صرف پورے سائز پر نہیں۔ سرخیوں کو 2 سے 22 فیصد حد کے اوپری حصے کے قریب سائز چاہیے ہوتا ہے، جبکہ کیپشن چھوٹے ہو سکتے ہیں۔ نتیجہ کو فون پر دیکھ کر آزمائیں۔"},{"question":"کیا تصویر پر متن لگانے سے اس کا لوکیشن ڈیٹا ہٹ جاتا ہے؟","answer":"ہاں، ٹول سے ایکسپورٹ کرنے پر EXIF GPS ٹیگ فائل سے ہٹ جاتے ہیں۔ متن تصویر میں جڑ جاتا ہے اور لوکیشن ریکارڈ اسی مرحلے میں ہٹ جاتا ہے۔ اگر آپ لوکیشن محفوظ رکھنا چاہتے ہیں تو اصل فائل رکھیں۔"}];
